local T=dofile('tests/kernel_subscription_harness.lua');local checks=0
local function test(label,fn)fn();checks=checks+1 end
test('constructor inert',function()local r=T.unit();r.prepare();assert(r.attempts==0 and #r.calls==0)end)
test('explicit once-only install',function()local r=T.unit();r.prepare();assert(r.api.Install()and r.attempts==2 and not r.api.Install())end)
test('names and same handler targets copied',function()local r=T.unit();r.prepare();local a=r.api.Describe();assert(a[1].key=='one'and a[1].handler==r.spec.entries[1].handler);a[1].key='mutated';assert(r.api.Describe()[1].key=='one')end)
test('spec mutations cannot redirect frozen registration',function()local r=T.unit();r.prepare();r.spec.entries[1].key='other';r.spec.subscribe=function()error('replaced')end;r.api.Install();r.emit('one',5);assert(r.calls[1][1]==5)end)
test('nil arguments and multiple returns preserved',function()local r=T.unit();r.prepare();r.api.Install();local v=r.emit('one',nil,4,nil);assert(v.n==3 and v[1]==nil and v[2]==7 and v[3]==nil and r.calls[1].n==3 and r.calls[1][2]==4)end)
test('payload identity preserved at wrapper boundary',function()local r=T.unit();r.prepare();r.api.Install();local data={};r.emit('one',data);assert(r.calls[1][1]==data)end)
test('same domain distinct listeners retain order',function()local r=T.unit();r.spec.entries[2].key='one';r.prepare();r.api.Install();r.emit('one','value');assert(#r.calls==2 and r.registered[1].key=='one'and r.registered[2].key=='one')end)
test('duplicate key/function refused before ownership',function()local r=T.unit();r.spec.entries[2]=r.spec.entries[1];assert(not pcall(r.prepare)and r.spec.owner.WorldSubscriptionRegistration==nil and r.attempts==0)end)
test('invalid descriptor refused',function()local r=T.unit();r.spec.entries[1].handler=nil;assert(not pcall(r.prepare)and r.attempts==0)end)
test('foreign owner never overwritten',function()local r=T.unit();local foreign={};r.spec.owner.WorldSubscriptionRegistration=foreign;assert(not pcall(r.prepare)and r.spec.owner.WorldSubscriptionRegistration==foreign)end)
test('no implicit replay on install',function()local r=T.unit();r.prepare();r.api.Install();assert(#r.calls==0)end)
test('synchronous provider delivery remains inactive until commit',function()local r=T.unit();r.onSubscribe=function(_,fn)fn('inline')end;r.prepare();r.api.Install();assert(#r.calls==0);r.emit('one','after');assert(#r.calls==1)end)
test('dispose leaves only logically revoked shells',function()local r=T.unit();r.prepare();r.api.Install();assert(r.api.Dispose()and #r.registered==2 and r.api.PhysicalUnregistration==false);r.emit('one',3);assert(#r.calls==0 and not r.api.Dispose()and not r.api.Install())end)
test('public State cannot resurrect dispatch',function()local r=T.unit();r.prepare();r.api.Install();r.api.Dispose();r.api.State='installed';r.emit('one',3);assert(#r.calls==0 and not r.api.Install())end)
test('dispose before install has no provider effect',function()local r=T.unit();r.prepare();assert(r.api.Dispose()and not r.api.Install()and r.attempts==0)end)
test('foreign subscriptions preserved',function()local r=T.unit();local called=false;r.registered[1]={key='foreign',handler=function()called=true end};r.prepare();r.api.Install();r.api.Dispose();r.emit('foreign');assert(called and #r.registered==3)end)
test('partial throwing provider remains revoked without retry',function()local r=T.unit();r.failAt=2;r.prepare();assert(not pcall(r.api.Install)and r.attempts==2);r.emit('one',4);r.emit('two',4);assert(#r.calls==0 and not r.api.Install())end)
test('canonical replacement prevents publication',function()local r=T.unit();r.prepare();r.replaced=true;assert(not pcall(r.api.Install)and r.attempts==0)end)
test('replacement during publication revokes prefix',function()local r=T.unit();r.onSubscribe=function()r.replaced=true end;r.prepare();assert(not pcall(r.api.Install)and r.attempts==1);r.emit('one');assert(#r.calls==0)end)
test('replacement after installation prevents dispatch',function()local r=T.unit();r.prepare();r.api.Install();r.replaced=true;r.emit('one',5);assert(#r.calls==0)end)
test('reentrant disposal during publication cannot reactivate',function()local r=T.unit();r.onSubscribe=function()r.api.Dispose()end;r.prepare();assert(not pcall(r.api.Install)and r.attempts==1);r.emit('one');assert(#r.calls==0)end)
test('reentrant install does not publish twice',function()local r=T.unit();r.onSubscribe=function()assert(not r.api.Install())end;r.prepare();r.api.Install();assert(r.attempts==2)end)
test('yielded guard rechecks revocation before business body',function()local r=T.unit();r.prepare();r.api.Install();r.yieldGuard=true;local co=coroutine.create(function()r.emit('one',1)end);local ok,value=coroutine.resume(co);assert(ok and value=='guard');r.api.Dispose();assert(coroutine.resume(co)and #r.calls==0)end)
test('entered consumer may finish after disposal',function()local r=T.unit();r.spec.entries[1].handler=function()coroutine.yield('body');r.finished=true end;r.prepare();r.api.Install();local co=coroutine.create(function()r.emit('one')end);assert(coroutine.resume(co));r.api.Dispose();assert(coroutine.resume(co)and r.finished)end)
test('errors not swallowed by registration wrapper',function()local r=T.unit();r.spec.entries[1].handler=function()error('consumer error',0)end;r.prepare();r.api.Install();local ok,err=pcall(r.emit,'one');assert(not ok and err=='consumer error')end)
print('PASS lot55 subscriptions: '..checks..' ownership checks; no replay/workers/IO, exact payload/returns, canonicality/partial failure/reentry/revocation; physical removal unavailable')
